var COUPLETS=[
 ['一帆风顺年年好','万事如意步步高','吉星高照'],
 ['春风得意千般顺','和气致祥百业兴','迎春接福'],
 ['岁岁平安添百福','年年顺景纳千祥','欢度佳节'],
 ['瑞雪纷飞丰稔岁','红梅绽放太平春','山河锦绣'],
 ['生意兴隆通四海','财源茂盛达三江','昌盛发达'],
 ['风和日丽春光好','水绿山青画意浓','锦绣河山'],
 ['喜居宝地千年旺','福照家门万事兴','五福临门'],
 ['书山有路勤为径','学海无涯苦作舟','励志笃行'],
 ['海纳百川有容乃大','壁立千仞无欲则刚','虚怀若谷'],
 ['宝剑锋从磨砺出','梅花香自苦寒来','自强不息'],
 ['但愿人长久','千里共婵娟','花好月圆'],
 ['两个黄鹂鸣翠柳','一行白鹭上青天','春和景明']
];
function pickCouplet(rng){
  rng=rng||Math.random;
  var i=Math.floor(rng()*COUPLETS.length);
  var c=COUPLETS[i];
  return {up:c[0], down:c[1], tag:c[2]};
}
function allCouplets(){ return COUPLETS.map(function(c){return {up:c[0],down:c[1],tag:c[2]};}); }
var EXPORTS={pickCouplet:pickCouplet, allCouplets:allCouplets};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CoupletForgePure = EXPORTS; }
